String money(num n) => NumberFormat.currency(locale: 'en_IN', symbol: '₹', decimalDigits: 0).format(n);
void main() async { WidgetsFlutterBinding.ensureInitialized(); await AppDatabase.instance.db; runApp(const InventoryApp()); }

